// @generated by archebuild — do not edit. Regenerated each build.

import { Handle } from '../scene/hit_test';
import { Tool } from '../ui_state/ui_state';

export function cursorFor(tool: Tool, hovering: boolean, panning: boolean, handle?: Handle): string {
  if (handle !== undefined) {
    if (handle === 'nw' || handle === 'se') {
      return 'nwse-resize';
    }
    if (handle === 'ne' || handle === 'sw') {
      return 'nesw-resize';
    }
    if (handle === 'n' || handle === 's') {
      return 'ns-resize';
    }
    return 'ew-resize';
  }

  if (tool === 'hand') {
    return panning ? 'grabbing' : 'grab';
  }

  if (tool === 'annotation') {
    return 'crosshair';
  }

  if (tool === 'select' && hovering) {
    return 'move';
  }

  return 'default';
}
